package com.bank.approvcyc.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// DFS three-colour cycle detection over approval-step dependencies.
public class ApprovalCycleService {
    private static final Logger log = Logger.getLogger(ApprovalCycleService.class.getName());

    private static final int WHITE = 0, GREY = 1, BLACK = 2;

    public boolean hasCircularDependency(int stepCount, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < stepCount; i++) adj.add(new ArrayList<>());
        for (int[] p : prerequisites) adj.get(p[0]).add(p[1]); // prerequisite → dependent
        int[] color = new int[stepCount];           // all WHITE initially
        for (int i = 0; i < stepCount; i++) {
            if (color[i] == WHITE && dfsHasCycle(i, adj, color)) {
                log.severe("Circular dependency detected among approval steps");
                return true;
            }
        }
        log.info("No circular dependency; approval workflow is safe");
        return false;
    }

    private boolean dfsHasCycle(int node, List<List<Integer>> adj, int[] color) {
        color[node] = GREY;                         // node now on the recursion stack
        for (int next : adj.get(node)) {
            if (color[next] == GREY) return true;    // back edge to an ancestor: cycle
            if (color[next] == WHITE && dfsHasCycle(next, adj, color)) return true;
        }
        color[node] = BLACK;                        // fully explored, no cycle through here
        return false;
    }
}
