package com.bank.approvcyc;

import com.bank.approvcyc.service.ApprovalCycleService;
import java.util.logging.Logger;

public class ApprovalCycleApplication {
    private static final Logger log = Logger.getLogger(ApprovalCycleApplication.class.getName());

    public static void main(String[] args) {
        ApprovalCycleService service = new ApprovalCycleService();
        int[][] prereqs = {{0, 1}, {1, 2}, {2, 0}}; // a deliberate loop
        boolean cycle = service.hasCircularDependency(3, prereqs);
        log.info("Approval workflow has a circular dependency: " + cycle);
    }
}
